/* RecipeMapper.selectHashtagSeqByName : 해시태그 시퀀스 조회 */
SELECT HSTG_SEQ
FROM HASHTAG
WHERE HSTG_NM = #{tagNm}
  AND DEL_YN = 'N'

mapper.delete:
/* RecipeMapper.deleteRecipeHashtags : 레시피 해시태그 매핑 전체 삭제 (논리 삭제) */
UPDATE RECIPE_HASHTAG
SET DEL_YN = 'Y'
WHERE RECIPE_SEQ = #{recipeSeq}

mapper.select:
/* RecipeMapper.checkUserLike : 사용자 좋아요 여부 확인 (0: 안 누름, 1: 누름(del_yn=N), -1: 취소됨(del_yn=Y)) */
SELECT CASE 
         WHEN DEL_YN = 'N' THEN 1 
         ELSE -1 
       END AS LIKE_STATUS
FROM LIKES
WHERE TGT_SEQ = #{tgtSeq}
  AND USER_SEQ = (SELECT USER_SEQ FROM USERS WHERE USER_KEY = #{userKey} AND DEL_YN = 'N')
  AND TGT_TY = #{tgtTy}
